mapper.update:
UPDATE story_session
   SET prepared = 0, started_at = NOW()
 WHERE session_id = #{sessionId}

UPDATE story_session
   SET status   = #{status}
     , ended_at = NOW()
 WHERE session_id = #{sessionId}
   AND status != 'COMPLETED'

mapper.select:
SELECT DISTINCT CAST(started_at AS DATE) d
  FROM story_session
 WHERE child_id = #{childId}
 ORDER BY d DESC
 LIMIT #{limit}
